SPDX-License-Identifier: MIT-0
"""

from __future__ import unicode_literals

import os
import regex as re
from typing import Any

from cfnlint._typing import RuleMatches
from cfnlint.rules import CloudFormationLintRule, RuleMatch
from cfnlint.template import Template
from cfnlint.decode import cfn_yaml


class Used(CloudFormationLintRule):
    """Check if Parameters are used"""

    id = "W2001"
    shortdesc = "Check if Parameters are Used"
    description = "Making sure the parameters defined are used"
    source_url = "https://github.com/aws-cloudformation/cfn-lint"
    tags = ["parameters"]

    def _collect_refs_and_subs_from_obj(self, obj: Any) -> tuple[list[str], list[str]]:
        """Recursively collect Ref and Fn::Sub parameter usages from a parsed object.

        Returns a tuple of (refs, subs) containing parameter names referenced.
        """
        refs: list[str] = []
        subs: list[str] = []

        def walk(v: Any) -> None:
            nonlocal refs, subs
            if isinstance(v, dict):
                # handle single-key function dicts first
                if len(v) == 1:
                    for k, val in v.items():
                        if k == "Ref" and isinstance(val, str):
                            refs.append(val)
                        elif k == "Fn::Sub":
                            # list form
                            if isinstance(val, list):
                                if val and isinstance(val[0], str):
                                    subs.extend(self._extract_sub_params(val[0]))
                            # string form
                            elif isinstance(val, str):
                                subs.extend(self._extract_sub_params(val))
                        else:
                            walk(val)
                else:
                    for k, val in v.items():
                        # also catch nested refs/subs even if mixed with other keys
                        if k == "Ref" and isinstance(val, str):
                            refs.append(val)
                        elif k == "Fn::Sub":
                            if isinstance(val, list):
                                if val and isinstance(val[0], str):
                                    subs.extend(self._extract_sub_params(val[0]))
                            elif isinstance(val, str):
                                subs.extend(self._extract_sub_params(val))
                        else:
                            walk(val)
            elif isinstance(v, list):
                for item in v:
                    walk(item)

        walk(obj)
        return refs, subs

    def _extract_sub_params(self, s: str) -> list[str]:
        """Extract parameter names from Fn::Sub strings.

        Supports both standard ${Param} and double-brace ${{Param}} syntax seen in
        some included OpenAPI specifications.
        """
        params: list[str] = []
        if not isinstance(s, str):
            return params
        # standard ${Param}
        for m in re.findall(r"\${([^!].*?)}", s):
            params.append(m.strip())
        # double-brace ${{Param}}
        for m in re.findall(r"\$\{\{([^!].*?)\}\}", s):
            params.append(m.strip())
        return params

    def _collect_from_includes(self, cfn: Template) -> tuple[list[str], list[str]]:
        """Locate AWS::Include transforms and collect parameter usages from included files."""
        include_refs: list[str] = []
        include_subs: list[str] = []

        # find Fn::Transform occurrences
        transform_paths = cfn.search_deep_keys("Fn::Transform")
        for path in transform_paths:
            if not path:
                continue
            transform_val = path[-1]
            if not isinstance(transform_val, dict):
                continue
            name = transform_val.get("Name")
            if name != "AWS::Include":
                continue
            params = transform_val.get("Parameters")
            if not isinstance(params, dict):
                continue
            location = params.get("Location")
            if not isinstance(location, str):
                continue
            # skip remote locations
            if location.startswith("s3://") or location.startswith("http://") or location.startswith("https://"):
                continue
            # resolve path relative to main template file
            try:
                base = os.path.dirname(cfn.filename) if cfn.filename else ""
                include_path = os.path.normpath(os.path.join(base, location))
            except Exception:
                continue
            # load included file
            try:
                included_obj = cfn_yaml.load(include_path)
            except Exception:
                continue
            if not isinstance(included_obj, dict):
                continue
            refs, subs = self._collect_refs_and_subs_from_obj(included_obj)
            include_refs.extend(refs)
            include_subs.extend(subs)

        return include_refs, include_subs

    def match(self, cfn: Template) -> RuleMatches:
        matches: RuleMatches = []

        le_refs = None
        if cfn.has_language_extensions_transform():
            le_refs = cfn.search_deep_keys("Ref")

        reftrees = cfn.transform_pre.get("Ref", [])
        subtrees = cfn.transform_pre.get("Fn::Sub", [])
        refs: list[str] = []
        for reftree in reftrees:
            refs.append(reftree[-1])
        if le_refs:
            for le_ref in le_refs:
                if le_ref[-1] not in refs:
                    refs.append(le_ref[-1])

        subs: list[str] = []
        for subtree in subtrees:
            if isinstance(subtree[-1], list):
                subs.extend(cfn.get_sub_parameters(subtree[-1][0]))
            elif isinstance(subtree[-1], str):
                subs.extend(cfn.get_sub_parameters(subtree[-1]))

        # additionally scan included files referenced by Fn::Transform AWS::Include
        include_refs, include_subs = self._collect_from_includes(cfn)
        for r in include_refs:
            if r not in refs:
                refs.append(r)
        subs.extend(include_subs)

        for paramname in cfn.template.get("Parameters", {}).keys():
            if paramname not in refs and paramname not in subs:
                message = "Parameter {0} not used."
                matches.append(
                    RuleMatch(["Parameters", paramname], message.format(paramname))
                )

        return matches
